#!/usr/bin/env python3
"""Writes lib/assistant/guide.g.dart from docs/ASSISTANT_GUIDE.md (the
assistant's built-in knowledge, shared with 1.x). Run after editing the guide."""
import pathlib
root = pathlib.Path(__file__).resolve().parents[2]
text = (root / 'docs' / 'ASSISTANT_GUIDE.md').read_text(encoding='utf-8')
assert "'''" not in text
out = root / 'dj_assistant_flutter' / 'lib' / 'assistant' / 'guide.g.dart'
out.write_text(
    '// Generated by tool/gen_guide.py from docs/ASSISTANT_GUIDE.md. Do not edit.\n\n'
    '/// The assistant\'s built-in knowledge of the app (its system prompt).\n'
    "const assistantGuide = r'''" + text + "''';\n",
    encoding='utf-8',
)
